 "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">5</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Secar y encuadernar</b><br><span style=\"color:#6b6b6b\">Pliegos al aire; luego, coser el libro</span></span></div>": "<div style=\"display:flex;gap:18px;align-items:center\"><span style=\"flex:0 0 52px;height:52px;border-radius:26px;background:#b0201c;color:#fff;font-weight:700;text-align:center;line-height:52px;font-size:28px\">5</span><span><b style=\"font-family:'Playfair Display', serif;font-size:28px\">Drogen en binden</b><br><span style=\"color:#6b6b6b\">Vellen aan de lucht; daarna het boek naaien</span></span></div>",
